  position: absolute;
  left: 1rem;
  top: -40px;
  background: var(--surface);
  color: var(--text);
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  text-decoration: none;
  box-shadow: var(--shadow-md);
  z-index: 100;
}
.skip-link:focus {
  top: 1rem;
}

.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 2rem;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.brand {
  font-weight: 600;
  letter-spacing: 0.02em;
}

.nav-list {
  display: flex;
  gap: 1.25rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.nav-list a {
  color: var(--text-muted);
  text-decoration: none;
  padding: 0.25rem 0.5rem;
  border-radius: 6px;
  font-size: 0.95rem;
}
.nav-list a:hover {
  color: var(--text);
}
.nav-list a[aria-current="page"] {
  color: var(--text);
  background: var(--surface-2);
}

.preview {
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

.crumbs ol {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0;
  margin: 0 0 1.25rem;
  font-size: 0.875rem;
  color: var(--text-muted);
}
.crumbs li + li::before {
  content: "/";
  margin-right: 0.5rem;
  color: var(--border);
}
.crumbs a {
  color: var(--text-muted);
  text-decoration: none;
}
.crumbs a:hover {
  color: var(--text);
  text-decoration: underline;
}
.crumbs [aria-current="page"] {
  color: var(--text);
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.image-frame {
  margin: 0;
}
.image-frame img {
  display: block;
  width: 100%;
  height: auto;
  background: var(--surface-2);
}

.meta {
  padding: 1.25rem 1.5rem 0.5rem;
}
.meta h1 {
  margin: 0 0 0.75rem;
  font-size: 1.375rem;
  font-weight: 600;
}
.meta-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 0.75rem 1.5rem;
  margin: 0;
}
.meta-list > div {
  display: flex;
  flex-direction: column;
}
.meta-list dt {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
}
.meta-list dd {
  margin: 0.125rem 0 0;
  font-size: 0.9375rem;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 1rem 1.5rem 1.5rem;
  border-top: 1px solid var(--border);
  margin-top: 1rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font: inherit;
  font-weight: 500;
  font-size: 0.9375rem;
  padding: 0.5rem 0.95rem;
  min-height: 40px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease,
    color 0.15s ease, box-shadow 0.15s ease;
}
.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.btn-secondary {
  background: var(--surface);
  border-color: var(--border);
  color: var(--text);
}
.btn-secondary:hover:not(:disabled) {
  background: var(--surface-2);
}

.btn-danger {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger);
}
.btn-danger:hover:not(:disabled) {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
}

.status {
  margin: 0;
  padding: 0 1.5rem 1.25rem;
  font-size: 0.9375rem;
  color: var(--text-muted);
  min-height: 1.25rem;
}
.status:empty {
  padding: 0;
  min-height: 0;
}

/* Dialog */
.dialog {
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  max-width: 440px;
  width: calc(100% - 2rem);
  box-shadow: var(--shadow-lg);
}
.dialog::backdrop {
  background: rgba(15, 23, 42, 0.55);
  backdrop-filter: blur(2px);
}

@media (prefers-reduced-motion: no-preference) {
  .dialog[open] {
    animation: dialog-in 160ms ease-out;
  }
  .dialog[open]::backdrop {
    animation: backdrop-in 160ms ease-out;
  }
}
@keyframes dialog-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
}
@keyframes backdrop-in {
  from {
    opacity: 0;
  }
}

.dialog-form {
  margin: 0;
  padding: 1.5rem;
}
.dialog-form h2 {
  margin: 0 0 0.5rem;
  font-size: 1.125rem;
  font-weight: 600;
}
.dialog-form p {
  margin: 0 0 1.25rem;
  color: var(--text-muted);
  font-size: 0.9375rem;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  flex-wrap: wrap;
}

@media (max-width: 480px) {
  .site-header {
    padding: 1rem;
  }
  .dialog-actions {
    flex-direction: column-reverse;
  }
  .dialog-actions .btn {
    width: 100%;
    justify-content: center;
  }
}

@media (forced-colors: active) {
  .btn,
  .dialog,
  .card {
    border-color: CanvasText;
  }
  .btn-danger {
    background: Mark;
    color: MarkText;
  }
}
